import{_ as t,C as o,o as i,c as s,al as a,E as n}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"DroneCAN ESCs","description":"","frontmatter":{},"headers":[],"relativePath":"ko/dronecan/escs.md","filePath":"ko/dronecan/escs.md"}'),l={name:"ko/dronecan/escs.md"};function c(d,e,p,h,u,f){const r=o("Badge");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="dronecan-escs" tabindex="-1">DroneCAN ESCs <a class="header-anchor" href="#dronecan-escs" aria-label="Permalink to &quot;DroneCAN ESCs&quot;">​</a></h1><p>PX4 supports DroneCAN compliant ESCs.</p><h2 id="supported-esc" tabindex="-1">Supported ESC <a class="header-anchor" href="#supported-esc" aria-label="Permalink to &quot;Supported ESC&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="./../peripherals/esc_motors#supported-esc">Supported ESCs</a> in <em>ESCs &amp; Motors</em> may include additional devices that are not listed below.</p></div><p>The following articles have specific hardware/firmware information:</p><ul><li><a href="./sapog">PX4 Sapog ESC Firmware</a><ul><li><a href="./holybro_kotleta">Holybro Kotleta 20</a></li></ul></li><li><a href="./zubax_telega">Zubax Telega</a></li><li><a href="./../peripherals/vertiq">Vertiq</a> (larger modules)</li><li><a href="./../peripherals/vesc">VESC Project</a></li><li><a href="./raccoonlab_nodes">RaccoonLab Cyphal and DroneCAN PWM nodes</a></li></ul><h2 id="하드웨어-설정" tabindex="-1">하드웨어 설정 <a class="header-anchor" href="#하드웨어-설정" aria-label="Permalink to &quot;하드웨어 설정&quot;">​</a></h2><p>General DroneCAN hardware configuration is covered in <a href="./../dronecan/#hardware-setup">DroneCAN &gt; Hardware Setup</a>.</p><p>DroneCAN ESCs should be on their own dedicated CAN interface(s) because ESC messages can saturate the bus and starve other nodes of bandwidth.</p><h2 id="px4-설정" tabindex="-1">PX4 설정 <a class="header-anchor" href="#px4-설정" aria-label="Permalink to &quot;PX4 설정&quot;">​</a></h2><p>DroneCAN peripherals are configured by following the procedure outlined in <a href="./../dronecan/">DroneCAN</a>.</p><p>In addition to the general setup, such as setting <code>UAVCAN_ENABLE</code> to <code>3</code>:</p><ul><li>Select the specific CAN interface(s) used for ESC data output using the <a href="./../advanced_config/parameter_reference#UAVCAN_ESC_IFACE">UAVCAN_ESC_IFACE</a> parameter (all that all interfaces are selected by default).</li><li>Configure the <a href="./../config/actuators">motor order and servo outputs</a>.</li></ul><p>When ESC output is enabled, PX4 publishes <a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#armingstatus" target="_blank" rel="noreferrer">ArmingStatus</a> (<code>STATUS_FULLY_ARMED</code> while armed or during QGC actuator tests). ESCs that require that message work for both flight and the Actuators page without setting <a href="./../advanced_config/parameter_reference#UAVCAN_PUB_ARM">UAVCAN_PUB_ARM</a>.</p><h2 id="reversible-motors" tabindex="-1">Reversible Motors <a class="header-anchor" href="#reversible-motors" aria-label="Permalink to &quot;Reversible Motors {#reversible-motors}&quot;">​</a></h2>',15)),n(r,{type:"tip",text:"main (PX4 v2.0)"}),e[1]||(e[1]=a('<p>Motors can be reversible &quot;on the fly&quot; (bidirectional) if the motor hardware supports reversal, the ESC firmware is configured for 3D/bidirectional operation, and the motor is set as <a href="./../config/actuators#bidirectional-motors">bidirectional</a> in the actuator configuration.</p><p>When configured as bidirectional, PX4 commands the motor with a <em>signed</em> <code>uavcan.equipment.esc.RawCommand</code> value, as defined by the DroneCAN ESC message protocol:</p><ul><li><strong>Zero:</strong> Motor stop / neutral</li><li><strong>Positive values:</strong> Forward thrust</li><li><strong>Negative values:</strong> Reverse thrust</li></ul><p>Motors that are not configured as bidirectional continue to receive positive values only.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Verifying Operation Check the sign of the RPM reported in the ESC telemetry to confirm that the ESC is interpreting negative commands correctly and actively spinning the motor in reverse.</p></div><p>Reversible motors may also be used in <a href="./../config/motor_failure_recovery">Motor Failure Recovery</a> to keep a hexarotor controllable after a single motor failure. That case still needs ESCs configured for reversal. However it is not necessary to set the motor as bidirectional in the actuator configuration, because PX4 makes the recovery motor reversible as it handles the failure.</p>',6))])}const g=t(l,[["render",c]]);export{_ as __pageData,g as default};
